fn sum_range(xs: List[Int], i: Int, j: Int) -> Int
  requires i >= 0 and j <= len(xs) and i <= j
  ensures (i == j and result == 0) or (i < j and result == xs[i] + sum_range(xs, i + 1, j))
  effects pure
  example sum_range([1, 2, 3], 0, 0) == 0
  example sum_range([1, 2, 3], 0, 2) == 3
  example sum_range([1, 2, 3], 1, 3) == 5
{
  if i == j then 0
  else if i == 0 then match xs {
    [] => 0
    [h, ..t] => h + sum_range(t, 0, j - 1)
  }
  else match xs {
    [] => 0
    [_, ..t] => sum_range(t, i - 1, j - 1)
  }
}

fn max_int(a: Int, b: Int) -> Int
  requires a >= 0 and b >= 0
  ensures (result == a or result == b) and result >= a and result >= b
  effects pure
  example max_int(3, 5) == 5
  example max_int(5, 3) == 5
{
  if a >= b then a else b
}

fn find_max_ending_helper(xs: List[Int], start: Int, end: Int, max_so_far: Int) -> Int
  requires start >= 0 and start < end
  ensures forall j in (start + 1)..((start + end) + 1): (sum_range(xs, start, j) <= result) or (j > len(xs))
  effects pure
  example find_max_ending_helper([1, 2, 3], 0, 1, 0) == 1
  example find_max_ending_helper([1, 2, 3], 0, 3, 0) == 6
{
  match xs {
    [] => max_so_far
    [_, ..t] => find_max_ending_helper(t, start, end - 1, max_int(max_so_far, sum_range(xs, start, start + 1)))
  }
}

fn find_max_subarray_iter(xs: List[Int], max_so_far: Int) -> Int
  requires exists x in xs: (x > 0)
  ensures forall i in 0..len(xs): forall j in (i + 1)..(len(xs) + 1): (sum_range(xs, i, j) <= result)
  ensures result > 0
  effects pure
  example find_max_subarray_iter([1, -2, 3, 4, -1], 0) == 7
  example find_max_subarray_iter([2, 2, -5, 1], 0) == 4
  example find_max_subarray_iter([-3, 5, -10], 0) == 5
{
  match xs {
    [] => max_so_far
    [_, ..t] => find_max_subarray_iter(t, max_int(max_so_far, find_max_from_start(xs, 0, 1)))
  }
}

fn find_max_from_start(xs: List[Int], start: Int, end_offset: Int) -> Int
  requires start >= 0 and end_offset >= 1
  ensures forall j in (start + 1)..(len(xs) + 1): (sum_range(xs, start, j) <= result)
  effects pure
  example find_max_from_start([1, 2, 3], 0, 1) == 1
  example find_max_from_start([1, 2, 3], 0, 3) == 6
{
  match xs {
    [] => 0
    [_, ..t] => match t {
      [] => sum_range(xs, start, start + 1)
      _ => max_int(sum_range(xs, start, start + end_offset), find_max_from_start(xs, start, end_offset + 1))
    }
  }
}

fn max_subarray(xs: List[Int]) -> Int
  requires exists x in xs: (x > 0)
  ensures exists i in 0..len(xs): exists j in (i + 1)..(len(xs) + 1): (sum_range(xs, i, j) == result)
  ensures forall i in 0..len(xs): forall j in (i + 1)..(len(xs) + 1): (sum_range(xs, i, j) <= result)
  ensures result > 0
  effects pure
  example max_subarray([1, -2, 3, 4, -1]) == 7
  example max_subarray([2, 2, -5, 1]) == 4
  example max_subarray([-3, 5, -10]) == 5
{
  find_max_subarray_iter(xs, 0)
}

